// 设置时区偏移（东八区 UTC+8）
const timezoneOffset = 8;

// 获取上海时间
const now = new Date();
const localTime = new Date(now.getTime() + 
                          (now.getTimezoneOffset() * 60000) + 
                          (3600000 * timezoneOffset));

// 格式化工件
const year = localTime.getFullYear();
const month = String(localTime.getMonth() + 1).padStart(2, '0');
const day = String(localTime.getDate()).padStart(2, '0');
const formattedDate = `${year}-${month}-${day}`;
const dateNum = `${year}${month}${day}`;
const dayOfWeek = localTime.getDay();
const isWeekday = dayOfWeek >= 1 && dayOfWeek <= 5;
const timestamp = now.getTime();

// 处理每个输入item
for (const item of $input.all()) {
  // 添加URL
  item.json.url = `https://www.shfe.com.cn/data/tradedata/future/dailydata/kx${dateNum}.dat?params=${timestamp}`;

  // 添加日期信息
  item.json.date = formattedDate;
  item.json.dateNum = dateNum;
  item.json.weekday = isWeekday;
  item.json.timezone = `UTC+${timezoneOffset}`;
  item.json.dayOfWeek = dayOfWeek;
  item.json.weekdayName = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][dayOfWeek];
  item.json.timestamp = timestamp;
  item.json.isWeekend = !isWeekday;
}

return $input.all();

